class Stock
{
public:
    explicit Stock(int quantity) : m_quantity{ quantity < 0 ? 0 : quantity } {}

    int quantity() const { return m_quantity; }

    bool take(int amount)
    {
        if (amount <= 0 || amount > m_quantity)
        {
            return false;
        }
        m_quantity -= amount;
        return true;
    }

    void restock(int amount)
    {
        if (amount > 0)
        {
            m_quantity += amount;
        }
    }

private:
    int m_quantity{ 0 };
};

unitTests:
TEST("construction") { CHECK_EQ(Stock{ 5 }.quantity(), 5); CHECK_EQ(Stock{ -5 }.quantity(), 0); }
TEST("take what is there") { Stock s{ 5 }; CHECK(s.take(3)); CHECK_EQ(s.quantity(), 2); CHECK(s.take(2)); CHECK_EQ(s.quantity(), 0); }
TEST("cannot take too much or nonsense") { Stock s{ 2 }; CHECK(!s.take(3)); CHECK(!s.take(0)); CHECK(!s.take(-1)); CHECK_EQ(s.quantity(), 2); }
TEST("restock") { Stock s{ 1 }; s.restock(4); CHECK_EQ(s.quantity(), 5); s.restock(-10); s.restock(0); CHECK_EQ(s.quantity(), 5); }

